import React from 'react';

interface ClinicRowProps {
    name: string;
    address: string;
    instagram: string;
}

const ClinicRow: React.FC<ClinicRowProps> = ({ name, address, instagram }) => {
    return (
        <tr>
            <td>{name}</td>
            <td>{address}</td>
            <td>
                <a href={`https://instagram.com/${instagram}`} target="_blank" rel="noopener noreferrer">
                    {instagram}
                </a>
            </td>
        </tr>
    );
};

export default ClinicRow;
